    "Category": {
      "enum": [
        "shipping",
        "returns",
        "payment",
        "warranty",
        "order_status",
        "product_question",
        "other"
      ],
      "title": "Category",
      "type": "string"
    },
    "Priority": {
      "enum": [
        "low",
        "normal",
        "high",
        "urgent"
      ],
      "title": "Priority",
      "type": "string"
    }
  },
  "additionalProperties": false,
  "description": "Every field is required; `order_id` is null when the ticket names no order.",
  "properties": {
    "category": {
      "$ref": "#/$defs/Category"
    },
    "priority": {
      "$ref": "#/$defs/Priority"
    },
    "order_id": {
      "anyOf": [
        {
          "pattern": "^TS-\\d{6}$",
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "title": "Order Id"
    },
    "summary": {
      "maxLength": 200,
      "minLength": 1,
      "title": "Summary",
      "type": "string"
    }
  },
  "required": [
    "category",
    "priority",
    "order_id",
    "summary"
  ],
  "title": "TriageResult",
  "type": "object"
}

- category: what the ticket is about.
- priority: how urgent the ticket is.
- order_id: the order id from the ticket, or null.
- summary: one short sentence that describes the ticket.

Reply with the JSON object only.

